export type StoryLessonNumber = typeof storyLessonNumbers[number];
type Pair = [string, string];
type Choice = [string, string, string, 'A' | 'B'];
export interface Episode {
  title: string; skill: 'speaking' | 'listening' | 'reading';
  intro: Pair; goal: Pair; warmup: string; words: [string, string, string][];
  discussion: Pair; followup: string;
  tips: { rule: Pair; examples: Pair[] }[];
  apply: { situation: Pair; roles?: Pair; dialogue?: Pair[]; text?: string; questions: Pair[] };
  choose: Pair[]; choices: Choice[];
  mission: { situation: Pair; task: Pair; roles: Pair; text?: string; title?: string; lines: string[]; evidence: string; useful: string[] };
  topics: [string, string[]][]; trivia: Pair; triviaQuestion: Pair; closing: string;
}
export interface StoryLessonConfig {
  episode: Episode;
  id: string;
  chapterName: string;
  setting: string;
  previousSummary: string;
  storyNotes: string;
}
const bullets = (texts: string[]) => texts.map(text => ({ text }));
const questions = (items: Pair[]) => items.map(([question, answer]) => ({ question, answer }));
export const newBeginningWatercolor = (number: StoryLessonNumber, apiBase: string) => {
  const url = (section: string) => {
    const version = number === 6 && section === 'challenge1' ? 'v3' : number === 8 || (number === 4 && section === 'apply') ? 'v2' : 'v1';
    return `${apiBase.replace(/\/$/, '')}/lesson/files/lessons/conversational-skills/ja/l3-c1/new-beginning-watercolor-v1/lesson${number}-${section}-new-beginning-watercolor-${version}.webp`;
  };
  return { introduce: url('introduce'), apply: url('apply'), challenge1: url('challenge1') };
};
