// Reuse the established schema and guide layout, then replace every active story surface.
export function buildNewBeginningLesson(number: StoryLessonNumber, previous: any, apiBase: string, reference?: any, config?: StoryLessonConfig) {
  const e = config?.episode || newBeginningEpisodes[number], reading = e.skill === 'reading', listening = e.skill === 'listening';
  const base = buildArcLesson(reading ? 8 : 6, previous, apiBase, reference);
  const learn = base.learnData.steps[0];
  const compatibleArt = !config;
  const artwork = compatibleArt ? newBeginningWatercolor(number, apiBase) : null;
  const existingLearn = previous?.learnData?.steps?.[0];
  const applySteps: any[] = [
    { instruction: listening ? 'Set up the listening and read once for the main idea.' : reading ? 'Set up the reading and ask the student to read the complete text.' : 'Set up the dialogue and read it with the student. The tutor speaks first.',
      scripts: bullets([listening ? 'Listen for the main idea first. Is it clear?' : reading ? 'Please read the complete text. Is it clear?' : `I'll be ${e.apply.roles![0]}. Please be ${e.apply.roles![1]}. Is it clear? I'll start.`]),
      ...(listening ? { listeningScript: e.apply.text } : {}), tips: bullets([listening ? 'Only the tutor can see the transcript. Read slowly and naturally, then repeat for details. Repeat a requested sentence if needed.' : 'Read the situation first. Correct at most two or three important pronunciation errors after the activity.']) },
    { instruction: listening ? 'Ask the main-idea question, read again, then ask the detail questions.' : 'Ask the questions below and check the evidence for each answer.', questions: questions(e.apply.questions) },
  ];
  const missionSteps: any[] = [{ instruction: 'Read the situation and instructions, then check understanding.', scripts: bullets(['Please read the situation and instructions. Is it clear?']), tips: bullets(['Keep task information visible. Accept short, clear sentences.']) }];
  if (reading || listening) missionSteps.push({ instruction: reading ? 'Ask the student to read the complete passage before the roleplay.' : 'Read the complete message once for the main idea, then again for details.', ...(listening ? { listeningScript: e.mission.text } : { scripts: bullets(['Please read the whole text. You may look back at it during the conversation.']) }), tips: bullets([listening ? 'Only the tutor can see the script. Repeat the relevant part if requested; do not test exact wording.' : 'Keep the passage visible. Correct at most two or three important pronunciation errors after reading.']) });
  missionSteps.push(
    { instruction: 'Start the roleplay. The tutor speaks first; use follow-ups only when the student needs support.', scripts: bullets([`I'll be ${e.mission.roles[0]}. Please be ${e.mission.roles[1]}. You may use the useful language. I'll start.`, ...e.mission.lines.map((line, i) => `${i + 1}. ${line}`)]), tips: bullets(['Let the student finish before correcting. Follow the conversation naturally; skip lines already answered.', e.mission.evidence, 'Record actual incorrect responses with the existing assessment controls and tutor notes. Do not invent weaknesses.']) },
    { instruction: 'Give specific feedback and retry one part that needs support.', scripts: bullets([e.closing, "Great job! Let's go to the next part!"]), tips: bullets(['Give one specific success and one focused correction before the closing story line. Do Challenge 2 only if time remains.']) },
  );
  const next: any = {
    id: previous?.id || config?.id || newBeginningIds[number], skill: e.skill, chapterName: config?.chapterName || 'A New Beginning', lessonName: e.title, lessonTitle: `Lesson ${number}: ${e.title}`,
    goalTextEn: e.goal[0], goalTextJp: e.goal[1], backgroundImage: compatibleArt ? previous?.backgroundImage || artwork!.introduce : '',
    introductionData: { ...base.introductionData, introImage: compatibleArt ? previous?.introductionData?.introImage || artwork!.introduce : '', introTexts: [{ language: 'en', text: e.intro[0] }, { language: 'ja', text: e.intro[1] }], lessonGoalSteps: [
      { instruction: 'Introduce the lesson objective and check understanding.', script: `Our lesson objective today is to ${e.goal[0].replace(/^I can /, '').replace(/\.$/, '')}. Is it clear?` },
      { instruction: 'Introduce the situation.', script: `Here is our situation. ${e.intro[0]}` },
      { instruction: 'Ask the student a warm-up question.', script: e.warmup },
      { instruction: 'Transition to the next section.', script: "Great! Let's go to the next part!" },
    ] },
    learnData: { ...base.learnData, steps: [{ ...learn, stepType: 'vocabulary', stepName: 'STEP A: VOCABULARY', vocabularyItems: e.words.map(([englishText, highlightedWord, translation], i) => ({ englishText, highlightedWord, translation, image: compatibleArt ? existingLearn?.vocabularyItems?.[i]?.image || '' : '' })),
      discussionPart: { ...learn.discussionPart, instruction: e.discussion[0], instructionTranslation: e.discussion[1], images: [], tutorSteps: [
        { instruction: 'Introduce Part II.', script: "Okay, now let's do Part II." },
        { instruction: 'Read the instructions and check understanding.', script: `${e.discussion[0].replace(/^II\. /, '')} Is it clear?` },
        { instruction: 'Have the student answer using the vocabulary from Part I.', tip: 'Accept personal or invented details and short, clear sentences.' },
        { instruction: 'Ask one natural follow-up based on the answer.', script: e.followup, tip: 'Keep Part II to about one minute.' },
        { instruction: 'Transition to Part III.', script: "Good! Let's go to the next part!" },
      ] },
      pronunciationPart: { ...learn.pronunciationPart, tutorSteps: learn.pronunciationPart.tutorSteps.map((step: any, i: number) => i === 4 ? { ...step, script: `Great! Let's go to Step B ${reading ? 'Reading' : 'Grammar'} Tip!` } : step) },
    }] },
    stepBData: { stepType: 'grammar-tip', grammarTip: { ...base.stepBData.grammarTip, stepName: `STEP B: ${reading ? 'READING' : 'GRAMMAR'} TIP`, explanations: e.tips.map(tip => ({ ruleText: tip.rule[0], ruleTranslation: tip.rule[1], examplesTitle: 'EXAMPLES', examples: tip.examples.map(([sentence, translation]) => ({ sentence, translation })) })), tutorSteps: [
      { instruction: `Read the ${reading ? 'reading' : 'grammar'} tips and ask the student to read the examples.`, script: 'Please read the examples. Notice how the wording changes the meaning.' },
      { instruction: 'Check understanding with one question.', script: e.followup, tip: 'Accept a personal or invented answer. Give one brief correction if needed.' },
    ] } },
    applyData: { ...base.applyData, activityType: e.skill, activityTitle: e.skill.toUpperCase(), situationText: e.apply.situation[0], situationTranslation: e.apply.situation[1], situationImage: compatibleArt ? previous?.applyData?.situationImage || artwork!.apply : '', readingImage: '', readingImageLabel: '', readingText: reading ? e.apply.text : '', dialogueLines: (e.apply.dialogue || []).map(([speaker, text]) => ({ speaker, text, isAction: false })), tutorSteps: applySteps,
      triviaEnabled: true, triviaText: e.trivia[0], triviaTranslation: e.trivia[1], triviaImage: '', triviaTutorSteps: [
        { instruction: 'Introduce the trivia.', scripts: bullets(["Let's look at the trivia."]) },
        { instruction: 'Ask the student to read the trivia.', scripts: bullets(['Please read the trivia.']) },
        { instruction: 'Check understanding and ask the question below.', questions: questions([e.triviaQuestion]) },
        { instruction: 'Transition to Exercise.', scripts: bullets(["Great! Let's go to the next part!"]) },
      ] },
    exerciseData: { ...base.exerciseData, stepAType: 'choose', stepBType: 'multiple-choice', hasStepB: true, instructions: 'Choose the correct word or phrase. Then read the complete sentence.', instructionsTranslation: '正しい語や表現を選び、文全体を読みましょう。', chooseItems: e.choose.map(([sentence]) => ({ sentence })), answers: bullets(e.choose.map(([, answer]) => answer)), tutorSteps: [{ instruction: 'Have the student choose each phrase, then read the whole sentence.', scripts: bullets(['Choose an answer, then read the complete sentence.']), answerKey: bullets(e.choose.map(([, answer], i) => `${i + 1}. ${answer}`)), tips: bullets(['Mark each item using the existing controls and note actual incorrect responses.']) }], stepBInstruction: 'Read each situation or detail. Choose the best answer.', stepBInstructionTranslation: 'それぞれの場面や情報を読み、最も適切な答えを選びましょう。', multipleChoiceItems: e.choices.map(([boldSentence, optionA, optionB]) => ({ boldSentence, optionA, optionB })), stepBTutorSteps: [
      { instruction: 'Have the student read each item and choose an answer.', scripts: bullets(['Which words or details support your answer?']), tips: bullets(['Keep the items visible. Mark each item and record actual mistakes.']) },
      { instruction: 'Check the answers and correct only the parts that need support.', answerKey: bullets(e.choices.map((c, i) => `${i + 1}. ${c[3]} - ${c[c[3] === 'A' ? 1 : 2]}`)) },
    ] },
    missionData: { ...base.missionData, missionType: e.skill, situation: e.mission.situation[0], situationTranslation: e.mission.situation[1], instruction: e.mission.task[0], instructionTranslation: e.mission.task[1], grammarTipItems: e.mission.useful, image: compatibleArt ? previous?.missionData?.image || artwork!.challenge1 : '', questions: [], tutorSteps: missionSteps },
    missionData2: { ...base.missionData2, missionType: 'discussion', topics: e.topics.map(([title, items]) => ({ title, questions: items })), tutorSteps: [
      { instruction: 'Ask the student to choose one discussion topic.', scripts: bullets(['Please choose a topic. You may use your own or an imagined example.']), tips: bullets(['Skip this optional part if more time is needed for Challenge 1 or Feedback.']) },
      { instruction: 'Use the questions as guides and ask natural follow-ups.', tips: bullets(['This is general free talk, not a quiz about the characters.']) },
    ] },
    feedbackData: { ...base.feedbackData, goal: e.goal[0], goalJp: e.goal[1], rememberNote: `Base the objective score mainly on Challenge 1. ${reading ? 'Assess reading evidence separately from grammar in spoken explanations.' : listening ? 'Assess listening understanding separately from grammar in the retelling.' : 'Assess the dialogue and responses, not speech length.'} Give specific range, accuracy, and fluency feedback from observed performance.` },
    storyData: { enabled: previous?.storyData?.enabled ?? true, storyTitle: 'A New Beginning', setting: 'Kamo House, a small residence near the Kamo River in Kyoto, with a cafe downstairs. All characters are adults.', characters: [
      { id: 'emma', name: 'Emma', role: 'main', description: 'A graphic designer starting a new life in Kyoto. She enjoys photography and rents a room at Kamo House.' },
      { id: 'claire', name: 'Claire', role: 'supporting', description: 'A warm, welcoming Kamo House resident who helps run the cafe and suggests the exhibition.' },
      { id: 'leo', name: 'Leo', role: 'supporting', description: 'Moved from Bristol to Kyoto for a bakery job. Helps at the cafe every Sunday and prepares the exhibition snacks.' },
      { id: 'nao', name: 'Nao', role: 'supporting', description: 'A Kamo House resident from Fukuoka studying ceramics in Kyoto. Shares Emma\'s love of photography.' },
    ], previousSummary: number === 1 ? 'Emma is arriving in Kyoto to begin a new life.' : newBeginningEpisodes[requireDefined(storyLessonNumbers[storyLessonNumbers.indexOf(number) - 1], "storyLessonNumbers[storyLessonNumbers.indexOf(number) - 1]")].closing,
      currentEpisodeSummary: e.intro[0], currentPlotPoints: [e.intro[0], e.closing], nextEpisodeHook: e.closing,
      storyNotes: 'User-authored eight-part story, mapped to Lessons 1-4 and 6-9. Lesson 5 remains the checkpoint, not a separate story episode. The exhibition stays at the cafe on Sunday 2-4 p.m. Follow only the events in this story revision. No new artwork generated. Incompatible old scene images are cleared; originals remain in the migration backup.' },
  };
  // Never leave an obsolete receptive branch available for a renderer to pick up.
  delete next.missionData.readingPassage;
  delete next.missionData.listeningScript;
  if (reading) next.missionData.readingPassage = { title: e.mission.title, blocks: [{ type: 'paragraph', content: e.mission.text }], showAuthor: false, headerAlignment: 'left', closingQuestion: '' };
  if (reading && compatibleArt && next.missionData.image) next.missionData.readingPassage.blocks.push({ type: 'images', images: [next.missionData.image] });
  for (const key of ['readingPassage', 'listeningScript']) delete next.missionData2[key];
  // Existing fixed feedback definitions and score descriptors are never rewritten by story edits.
  if (previous?.feedbackData) {
    for (const key of ['categories', 'rubricLevels', 'rubricTitle', 'personalizedFeedbackTitle', 'feedbackGuideTitle']) if (previous.feedbackData[key] !== undefined) next.feedbackData[key] = structuredClone(previous.feedbackData[key]);
  }
  if (config) Object.assign(next.storyData, {
    storyTitle: config.chapterName, setting: config.setting, previousSummary: config.previousSummary,
    storyNotes: config.storyNotes,
  });
  return directRoleplayCopy(next);
}
